SELECT l.id, l.actor_id, a.nick_name AS actor_nick_name, l.action, l.target_type, l.target_id, t.nick_name AS target_nick_name, l.detail, l.created_at FROM admin_audit_logs l LEFT JOIN users a ON a.id = l.actor_id LEFT JOIN users t ON l.target_type = 'MEMBER' AND t.id = l.target_id
l.action = #{action}
l.target_type <> 'MAIL'
ORDER BY l.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM admin_audit_logs

    action = #{action}
    target_type <> 'MAIL'
